Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_compact_allocation_failure(void) {
    // Setup: create a buffer with extra capacity and some data
    buffer_t *buf = helper_make_buffer_with_data("hello world");
    TEST_ASSERT_NOT_NULL(buf);

    // Artificially increase buffer size to simulate unused capacity
    size_t old_size = buf->len;
    buf->len = old_size + 10; // Add unused space

    // Save original buffer state for later comparison
    char *original_data = NULL;
    if (buf->data) {
        size_t data_len = strlen(buf->data) + 1;
        original_data = (char *)malloc(data_len);
        TEST_ASSERT_NOT_NULL(original_data);
        memcpy(original_data, buf->data, data_len);
    }
    char *original_alloc = buf->alloc;
    size_t original_len = buf->len;

    // Simulate calloc failure on next allocation
    malloc_fail_next(1);

    // Test: call buffer_compact, which should fail to allocate
    ssize_t result = buffer_compact(buf);

    // Assertions: should return -1, buffer unchanged
    TEST_ASSERT_EQUAL(-1, result);
    TEST_ASSERT_EQUAL_PTR(original_alloc, buf->alloc);
    TEST_ASSERT_EQUAL_PTR(original_alloc, buf->data);
    TEST_ASSERT_EQUAL(original_len, buf->len);
    if (original_data) {
        TEST_ASSERT_EQUAL_STRING(original_data, buf->data);
    }

    // Cleanup
    if (original_data) free(original_data);
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_compact_allocation_failure);
    return UNITY_END();
}

